def find_initial_cards(n, d, l):
    # Try to find a valid initial set of cards
    for i in range(2**(n-1)):
        cards = [1] * n
        for j in range(n-1):
            if (i >> j) & 1:
                cards[j+1] = l

        current_d = d
        for j in range(n-1, 0, -1):
            a = cards[j-1]
            b = cards[j]
            cards[j-1] = min(a, b)
            cards[j] = max(a, b)
            current_d -= abs(a - b)

        if current_d == 0:
            return ' '.join(map(str, cards))

    return -1

